import re

def compact_log(log, k):
    pattern = re.compile(r'(.)\1{%d,}' % (k - 1))
    while True:
        new = pattern.sub('', log)
        if new == log:
            return log
        log = new

def compact_log(log, k):
    st = []
    for ch in log:
        st.append(ch)
        if len(st) >= k and st[-k:] == [ch] * k:
            del st[-k:]
    return ''.join(st)

ci-ring-waits.code:
def ring_waits(load):
    n = len(load)
    waits = []
    for i in range(n):
        w = -1
        for d in range(1, n):
            if load[(i + d) % n] > load[i]:
                w = d
                break
        waits.append(w)
    return waits

ci-tray-queue.code:
def solve_tray_queue(text):
    words = text.split()
    n = int(words[0]) if words else 0
    in_tray, out_tray = [], []
    served, moves = [], 0
    i = 1
    for _ in range(n):
        if words[i] == 'in':
            in_tray.append(words[i + 1])
            i += 2
            continue
        i += 1
        while in_tray:
            out_tray.append(in_tray.pop())
            moves += 1
        served.append(out_tray.pop() if out_tray else '0')
        while out_tray:
            in_tray.append(out_tray.pop())
            moves += 1
    return str(moves) + '\n' + ' '.join(served)

ci-wide-bars.code:
def largest_block_area(widths, heights):
    best = 0
    n = len(heights)
    for i in range(n):
        low, span = heights[i], 0
        for j in range(i, n):
            low = min(low, heights[j])
            span += widths[j]
            best = max(best, low * span)
    return best

ci-visible-masts.code:
def visible_masts(heights):
    n = len(heights)
    seen = []
    for i in range(n):
        count, tallest = 0, 0
        for j in range(i + 1, n):
            if tallest < min(heights[i], heights[j]):
                count += 1
            tallest = max(tallest, heights[j])
            if tallest > heights[i]:
                break
        seen.append(count)
    return seen

ci-price-ramp.code:
def widest_ramp(prices):
    n = len(prices)
    best = 0
    for i in range(n):
        for j in range(n - 1, i + best, -1):
            if prices[j] >= prices[i]:
                best = j - i
                break
    return best

ci-free-block.code:
def largest_free_block(rows):
    r = len(rows)
    best = 0
    for top in range(r):
        free = [True] * len(rows[0])
        for bottom in range(top, r):
            run = 0
            for j, ch in enumerate(rows[bottom]):
                free[j] = free[j] and ch == '.'
                run = run + 1 if free[j] else 0
                best = max(best, run * (bottom - top + 1))
    return best

ci-tick-ranges.code:
def solve_tick_ranges(text):
    v = text.split()
    n, q = int(v[0]), int(v[1])
    ticks = [int(x) for x in v[2:2 + n]]
    out = []
    for t in map(int, v[2 + n:2 + n + q]):
        if t in ticks:
            first = ticks.index(t)
            out.append(f'{first} {first + ticks.count(t) - 1}')
        else:
            out.append('-1 -1')
    return '\n'.join(out)

ci-ring-lookup.code:
def find_in_ring(ring, targets):
    out = []
    for t in targets:
        out.append(ring.index(t) if t in ring else -1)
    return out

ci-clear-rate.code:
def min_clear_rate(queues, minutes):
    r = 1
    while sum((q + r - 1) // r for q in queues) > minutes:
        r += 1
    return r

ci-relay-masts.code:
def min_longest_gap(relays, k):
    gaps = [b - a for a, b in zip(relays, relays[1:])]
    best = max(gaps)
    while best > 1 and sum((g - 1) // (best - 1) for g in gaps) <= k:
        best -= 1
    return best

ci-ready-blocks.code:
def earliest_ready_day(ready, k, m):
    if m * k > len(ready):
        return -1
    for day in sorted(set(ready)):
        count = run = 0
        for r in ready:
            if r <= day:
                run += 1
                if run == k:
                    count += 1
                    run = 0
            else:
                run = 0
        if count >= m:
            return day
    return -1
